() => {
      const LESSONS = 18, B = window.ebruDebug.BOT; let t = 0;
      const lessonsWithResult = () => new Set(B.log.filter((r) => !r.skipped).map((r) => r.lesson)).size;
      while (!B.done && lessonsWithResult() < LESSONS && B.lessonsDone < LESSONS && t < 3000) { window.ebruSim(10); t += 10; }
      // per lesson the last result (a lesson the bot fails is retried up to twice and logged each time)
      const last = new Map(); for (const r of B.log) if (!r.skipped && r.lesson <= LESSONS) last.set(r.lesson, r);
      const E = [...last.values()];
      window.__gateM = { lessons: B.lessonsDone, stars: E.reduce((a, r) => a + r.stars, 0), seals: E.filter((r) => r.seal).length,
        matchSum: Math.round(E.reduce((a, r) => a + r.match, 0) * 10) / 10, attempts: B.log.filter((r) => !r.skipped).length,
        skipped: B.log.filter((r) => r.skipped).length, strokes: E.reduce((a, r) => a + r.strokes, 0), simSeconds: t };
    }
